def explore_dataset(csv_path):
    df = pd.read_csv(csv_path)
    print(f"Total recordings: {len(df)}")
    print(f"Train/val/test split counts:\n{df['split'].value_counts()}")

    # Duration histogram
    plt.figure(figsize=(8,4))
    plt.hist(df['duration'], bins=50, color='steelblue', edgecolor='black')
    plt.xlabel('Duration (seconds)')
    plt.ylabel('Number of pieces')
    plt.title('MAESTRO Piece Duration Distribution')
    plt.savefig("plots/duration_histogram.png", dpi=150)
    plt.show()

    # Pitch distribution
    pitch_counter = Counter()
    sample_files = df.sample(min(20, len(df)))['midi_filename'].values
    for rel_path in sample_files:
        full_path = os.path.join(DATA_ROOT, rel_path)
        try:
            midi = pretty_midi.PrettyMIDI(full_path)
            for inst in midi.instruments:
                for note in inst.notes:
                    if PITCH_START <= note.pitch <= PITCH_END:
                        pitch_counter[note.pitch] += 1
        except:
            continue

    if pitch_counter:
        pitches = sorted(pitch_counter.keys())
        counts = [pitch_counter[p] for p in pitches]
        plt.figure(figsize=(10,4))
        plt.bar(pitches, counts, width=0.8, color='coral')
        plt.xlabel('MIDI Pitch')
        plt.ylabel('Note count')
        plt.title('Pitch Distribution (sample of pieces)')
        plt.savefig("plots/pitch_distribution.png", dpi=150)
        plt.show()

