# %% [markdown]
# ## 3. Preprocessing: MIDI → Piano‑Roll Windows

# %% [code]
def midi_to_pianoroll_windows(midi_path, fs=FS, window_len=WINDOW_LEN,
                              min_active_ratio=MIN_ACTIVE_RATIO):
    """Return list of windows (each shape (window_len, NUM_PITCHES))."""
    try:
        midi = pretty_midi.PrettyMIDI(midi_path)
        piano_roll = midi.get_piano_roll(fs=fs)[PITCH_START:PITCH_END+1, :]  # (88, T)
        piano_roll = piano_roll.T   # (T, 88)
        piano_roll = (piano_roll > 0).astype(np.float32)

        T_total = piano_roll.shape[0]
        windows = []
        for start in range(0, T_total - window_len + 1, window_len):
            win = piano_roll[start:start+window_len, :]
            if np.mean(win) >= min_active_ratio:
                windows.append(win)
        return windows
    except Exception as e:
        print(f"Error processing {midi_path}: {e}")
        return []

def preprocess_split(df_split, split_name):
    """Process all MIDI files in a given split and save windows."""
    out_file = f"pianoroll_{split_name}.npy"
    if os.path.exists(out_file):
        print(f"Loading existing {out_file}")
        return np.load(out_file)

    all_windows = []
    for _, row in tqdm(df_split.iterrows(), total=len(df_split), desc=f"Processing {split_name}"):
        midi_rel_path = row['midi_filename']
        midi_full_path = os.path.join(DATA_ROOT, midi_rel_path)
        windows = midi_to_pianoroll_windows(midi_full_path)
        all_windows.extend(windows)

    if not all_windows:
        raise RuntimeError(f"No windows generated for split {split_name}")

    data = np.stack(all_windows, axis=0)
    np.save(out_file, data)
    print(f"Saved {split_name} split: {data.shape}")
    return data

# Read splits from CSV
df_all = pd.read_csv(CSV_PATH)
train_df = df_all[df_all['split'] == 'train']
val_df   = df_all[df_all['split'] == 'validation']
test_df  = df_all[df_all['split'] == 'test']

train_data = preprocess_split(train_df, 'train')
val_data   = preprocess_split(val_df, 'validation')
test_data  = preprocess_split(test_df, 'test')

print(f"Train windows: {train_data.shape}, Val windows: {val_data.shape}, Test windows: {test_data.shape}")

# %% [markdown]
# ## 4. PyTorch Dataset & DataLoader

# %% [code]
class PianoRollDataset(Dataset):
    def __init__(self, data):
        self.data = torch.from_numpy(data).float()

    def __len__(self):
        return len(self.data)

    def __getitem__(self, idx):
        return self.data[idx]

train_dataset = PianoRollDataset(train_data)
val_dataset   = PianoRollDataset(val_data)
test_dataset  = PianoRollDataset(test_data)

train_loader = DataLoader(train_dataset, batch_size=BATCH_SIZE, shuffle=True, num_workers=2, pin_memory=True)
val_loader   = DataLoader(val_dataset,   batch_size=BATCH_SIZE, shuffle=False, num_workers=2)
test_loader  = DataLoader(test_dataset,  batch_size=BATCH_SIZE, shuffle=False, num_workers=2)

# %% [markdown]
# ## 5. LSTM Autoencoder Model with Focal Loss (α=0.95, γ=0)

# %% [code]
class Encoder(nn.Module):
    def __init__(self, input_dim, hidden_dim, latent_dim, num_layers):
        super().__init__()
        self.lstm = nn.LSTM(input_dim, hidden_dim, num_layers, batch_first=True, dropout=0.3 if num_layers > 1 else 0)
        self.dropout = nn.Dropout(0.3)
        self.fc = nn.Linear(hidden_dim, latent_dim)

    def forward(self, x):
        _, (h_n, _) = self.lstm(x)
        h_last = h_n[-1]
        h_last = self.dropout(h_last)
        z = self.fc(h_last)
        return z

class Decoder(nn.Module):
    def __init__(self, latent_dim, hidden_dim, output_dim, num_layers, seq_len, dropout=0.3):
        super().__init__()
        self.seq_len = seq_len
        self.dropout = nn.Dropout(dropout)
        self.lstm = nn.LSTM(latent_dim, hidden_dim, num_layers,
                            batch_first=True, dropout=dropout if num_layers>1 else 0)
        self.fc = nn.Linear(hidden_dim, output_dim)

    def forward(self, z):
        z_expanded = z.unsqueeze(1).repeat(1, self.seq_len, 1)
        out, _ = self.lstm(z_expanded)
        out = self.dropout(out)
        logits = self.fc(out)
        return logits

class LSTM_Autoencoder(nn.Module):
    def __init__(self, input_dim, hidden_dim, latent_dim, num_layers, seq_len):
        super().__init__()
        self.encoder = Encoder(input_dim, hidden_dim, latent_dim, num_layers)
        self.decoder = Decoder(latent_dim, hidden_dim, input_dim, num_layers, seq_len, dropout=0.3)

    def forward(self, x):
        z = self.encoder(x)
        recon_logits = self.decoder(z)
        return recon_logits, z

class FocalLoss(nn.Module):
    def __init__(self, alpha=0.95, gamma=0.0):
        super().__init__()
        self.alpha = alpha
        self.gamma = gamma

    def forward(self, inputs, targets):
        bce_loss = nn.functional.binary_cross_entropy_with_logits(inputs, targets, reduction='none')
        pt = torch.exp(-bce_loss)
        focal_weight = (1 - pt) ** self.gamma
        alpha_weight = targets * self.alpha + (1 - targets) * (1 - self.alpha)
        loss = alpha_weight * focal_weight * bce_loss
        return loss.mean()

# Instantiate model, loss, optimizer
model = LSTM_Autoencoder(input_dim=NUM_PITCHES,
                         hidden_dim=HIDDEN_DIM,
                         latent_dim=LATENT_DIM,
                         num_layers=NUM_LAYERS,
                         seq_len=WINDOW_LEN).to(device)

criterion = FocalLoss(alpha=0.95, gamma=0.0)   # α=0.95 gives 0.95 weight to notes, 0.05 to silence
optimizer = optim.Adam(model.parameters(), lr=LR)

print(f"Model parameters: {sum(p.numel() for p in model.parameters()):,}")

# %% [markdown]
# ## 6. Training Loop (with L1 penalty on latent)

# %% [code]
train_losses = []
val_losses = []

for epoch in range(1, EPOCHS+1):
    model.train()
    epoch_train_loss = 0.0
    for batch in train_loader:
        batch = batch.to(device)
        optimizer.zero_grad()
        recon_logits, z = model(batch)
        loss = criterion(recon_logits, batch)
        l1_penalty = 0.001 * torch.norm(z, p=1)   # encourages non‑zero latent
        loss = loss + l1_penalty
        loss.backward()
        optimizer.step()
        epoch_train_loss += loss.item() * batch.size(0)
    epoch_train_loss /= len(train_dataset)

    # Validation
    model.eval()
    epoch_val_loss = 0.0
    with torch.no_grad():
        for batch in val_loader:
            batch = batch.to(device)
            recon_logits, _ = model(batch)
            loss = criterion(recon_logits, batch)
            epoch_val_loss += loss.item() * batch.size(0)
    epoch_val_loss /= len(val_dataset)

    train_losses.append(epoch_train_loss)
    val_losses.append(epoch_val_loss)

    if epoch % 5 == 0:
        print(f"Epoch {epoch:2d}/{EPOCHS} | Train Loss: {epoch_train_loss:.4f} | Val Loss: {epoch_val_loss:.4f}")

# Plot loss curves
plt.figure(figsize=(10,5))
plt.plot(range(1, EPOCHS+1), train_losses, label='Train Loss')
plt.plot(range(1, EPOCHS+1), val_losses, label='Validation Loss')
plt.xlabel('Epoch')
plt.ylabel('Loss')
plt.title('Reconstruction Loss Curve (Focal α=0.95, γ=0)')
plt.legend()
plt.grid(True)
plt.savefig("plots/loss_curve.png", dpi=150)
plt.show()

# Trained model saving
torch.save(model.state_dict(), "model_task1.pt")
print("Model saved to model_task1.pt")

# %% [markdown]
# ## 7. Generate 5 MIDI Samples (with probability scaling and low threshold)

# %% [code]
def pianoroll_to_midi(pianoroll, fs=FS, threshold=GEN_THRESHOLD, velocity=80, min_duration=MIN_NOTE_DURATION):
    """Convert binary pianoroll (T, 88) to pretty_midi object."""
    midi = pretty_midi.PrettyMIDI(initial_tempo=120.0)
    piano = pretty_midi.Instrument(program=0, name='Piano')

    binary = (pianoroll >= threshold).astype(int)

    for pitch_idx in range(NUM_PITCHES):
        pitch = pitch_idx + PITCH_START
        note_on = False
        start_time = 0.0
        for t in range(binary.shape[0]):
            if binary[t, pitch_idx] == 1 and not note_on:
                note_on = True
                start_time = t / fs
            elif binary[t, pitch_idx] == 0 and note_on:
                note_on = False
                end_time = t / fs
                if end_time - start_time > min_duration:
                    note = pretty_midi.Note(velocity=velocity, pitch=pitch,
                                            start=start_time, end=end_time)
                    piano.notes.append(note)
        if note_on:
            end_time = binary.shape[0] / fs
            note = pretty_midi.Note(velocity=velocity, pitch=pitch,
                                    start=start_time, end=end_time)
            piano.notes.append(note)

    midi.instruments.append(piano)
    return midi

model.eval()
print("\nGenerating MIDI samples with probability scaling and low threshold...")
with torch.no_grad():
    for i in range(NUM_GEN_SAMPLES):
        z = torch.randn(1, LATENT_DIM).to(device)
        recon_logits = model.decoder(z)
        recon_probs = torch.sigmoid(recon_logits).cpu().numpy()[0]   # shape (T, 88)
        # Scale probabilities to boost weak note signals
        recon_probs_scaled = np.clip(recon_probs * PROB_SCALE, 0, 1)
        print(f"Sample {i+1}: original max prob = {recon_probs.max():.4f}, scaled max = {recon_probs_scaled.max():.4f}")
        midi_obj = pianoroll_to_midi(recon_probs_scaled, threshold=GEN_THRESHOLD, min_duration=MIN_NOTE_DURATION)
        out_path = f"generated_midi/generated_sample_{i+1}.mid"
        midi_obj.write(out_path)
        print(f"  Saved {out_path}")

